def transform(ctx):
    adj = ctx.book("expected_adjustments.xlsx")
    out = ctx.book("expected_output.xlsx")
    adj_rows = adj.read("AdjustData", "A2:B5")
    adjustments = {}
    for row in adj_rows:
        if row and row[0] not in (None, ""):
            adjustments[str(row[0])] = row[1] if len(row) > 1 and isinstance(row[1], (int, float)) else 0
    base_rows = out.read("ResultSheet", "A2:E5")
    write_rows = []
    for row in base_rows:
        code = str(row[0]) if row and row[0] not in (None, "") else ""
        base_amount = row[4] if len(row) > 4 and isinstance(row[4], (int, float)) else 0
        adjustment = adjustments.get(code, 0)
        write_rows.append([adjustment, base_amount + adjustment])
    out.write("ResultSheet", "F2", write_rows)

def transform(ctx):
    codes = ctx.book("expected_codes.xlsx")
    out = ctx.book("expected_output.xlsx")
    code_rows = codes.read("CodeMap", "A2:B5")
    category_by_code = {}
    for row in code_rows:
        if row and row[0] not in (None, ""):
            category_by_code[str(row[0])] = row[1] if len(row) > 1 else ""
    result_codes = out.read("ResultSheet", "A2:A5")
    categories = []
    for row in result_codes:
        code = str(row[0]) if row and row[0] not in (None, "") else ""
        categories.append([category_by_code.get(code, "")])
    out.write("ResultSheet", "H2", categories)

def transform(ctx):
    out = ctx.book("expected_output.xlsx")
    rows = out.read("ResultSheet", "A2:H5")
    try:
        out.add_sheet("Validation_Result")
    except Exception:
        pass
    total = 0
    filled = 0
    for row in rows:
        if row and row[0] not in (None, ""):
            filled += 1
        if len(row) > 6 and isinstance(row[6], (int, float)):
            total += row[6]
    out.write("Validation_Result", "A1", [["Check", "Value"], ["Rows", filled], ["FinalAmountTotal", total]])
